import type { ComponentModules } from './host.js'

/** Core module assets generated by Jco's explicit component instantiation mode. */
export const COMPONENT_MODULE_NAMES = [
  'monty.component.core.wasm',
  'monty.component.core2.wasm',
  'monty.component.core3.wasm',
  'monty.component.core4.wasm',
] as const

/** The protocol codec's core modules, loaded alone by a remote (WebSocket) pool. */
export const CODEC_MODULE_NAMES = [
  'monty-proto.component.core.wasm',
  'monty-proto.component.core2.wasm',
  'monty-proto.component.core3.wasm',
  'monty-proto.component.core4.wasm',
] as const

/** Resolves Jco's relative core-module path against the precompiled module map. */
export function getModule(modules: ComponentModules, path: string): WebAssembly.Module {
  const module = modules[path] ?? modules[path.replace(/^\.\//, '')]
  if (!module) throw new Error(`component core module is missing: ${path}`)
  return module
}
